local w,h=Map.GetGridSize(); if w~=@WIDTH@ or h~=@HEIGHT@ then error('map grid mismatch '..w..'x'..h) end; for _,id in ipairs({'RESOURCE_JAC_GOLD','RESOURCE_JAC_LACQUER'}) do local r=GameInfo.Resources[id]; if not r then error('missing resource '..id) end; if r.PrereqTech then error(id..' must not be gated by a tech') end end; for r in GameInfo.Resources() do if r.PrereqTech and not string.find(r.PrereqTech,'TECH_JAC_SENGOKU_',1,true) then error('official tech gate on '..r.ResourceType..': '..r.PrereqTech) end end; if GameInfo.Resources['RESOURCE_IRON'].PrereqTech~='TECH_JAC_SENGOKU_IRON_FORGING' then error('iron gate') end; for r in GameInfo.Resource_Harvests() do if r.PrereqTech and not string.find(r.PrereqTech,'TECH_JAC_SENGOKU_',1,true) then error('official tech harvest gate on '..r.ResourceType) end; if r.ResourceType=='RESOURCE_RICE' and r.PrereqTech~='TECH_JAC_SENGOKU_IRRIGATION_WORKS' then error('rice harvest gate '..tostring(r.PrereqTech)) end end; local hills=false; for r in GameInfo.Resource_ValidTerrains() do if r.ResourceType=='RESOURCE_SILVER' and r.TerrainType=='TERRAIN_GRASS_HILLS' then hills=true end end; if not hills then error('silver is not valid on grass hills') end; local plantation=GameInfo.Improvements['IMPROVEMENT_PLANTATION']; if not plantation.Buildable or plantation.PrereqTech~='TECH_JAC_SENGOKU_IRRIGATION_WORKS' then error('plantation not buildable from Irrigation Works') end; local improves={}; for r in GameInfo.Improvement_ValidResources() do improves[r.ResourceType..'>'..r.ImprovementType]=true end; for _,pair in ipairs({'RESOURCE_JAC_GOLD>IMPROVEMENT_MINE','RESOURCE_IRON>IMPROVEMENT_MINE','RESOURCE_JAC_LACQUER>IMPROVEMENT_PLANTATION','RESOURCE_TEA>IMPROVEMENT_PLANTATION','RESOURCE_SILK>IMPROVEMENT_PLANTATION'}) do if not improves[pair] then error('missing improvement '..pair) end end; local starts=@STARTS@; for _,s in ipairs(starts) do local t=Map.GetPlotByIndex(s[2]):GetResourceType(); if t~=GameInfo.Resources[s[3]].Index then error('start resource missing: '..s[1]) end end; local api=ExposedMembers.JAC_Resources; if not api then error('JAC_Resources API missing') end; local sites=@SITES@; local listed={}; for _,s in ipairs(api.GetSites()) do listed[s.id]=s end; for _,s in ipairs(sites) do local l=listed[s[1]]; if not l then error('deferred site missing: '..s[1]) end; if l.plot~=s[2] or l.resource~=s[3] then error('deferred site moved: '..s[1]) end; listed[s[1]]=nil end; for id in pairs(listed) do error('unexpected deferred site: '..id) end; return #starts..' start resources and '..#sites..' deferred sites present; plantation and mine rows in place'